    cards.forEach(card=>{
      const title = card.dataset.title || '';
      card.style.display = !query || title.includes(query) ? '' : 'none';
    });
  }
  search.addEventListener('input', filterCards);

  navButtons.forEach(button=>{
    button.addEventListener('click', ()=>{
      const filter = button.dataset.filter;
      if(filter === 'favorites'){
        cards.forEach(c=>c.style.display = ['kids book animals','dicing onions','k-pop generations'].includes(c.dataset.title) ? '' : 'none');
      }else{
        cards.forEach(c=>c.style.display = c.dataset.type === filter ? '' : 'none');
      }
      search.value = '';
      window.scrollTo({top:0,behavior:'smooth'});
    });
  });

